import re
import sys

_WS_MATCH = re.compile(r'[ \t\n\r]*').match
_NUMBER_MATCH = re.compile(r'-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?').match
_SIMPLE_STRING_MATCH = re.compile(r'"([^"\\\x00-\x1f]*)"').match
_STRING_CHUNK_MATCH = re.compile(r'[^"\\\x00-\x1f]*').match
_HEX4_MATCH = re.compile(r'[0-9a-fA-F]{4}').match

_ESCAPES = {
    '"': '"',
    '\\': '\\',
    '/': '/',
    'b': '\b',
    'f': '\f',
    'n': '\n',
    'r': '\r',
    't': '\t',
}

_INT_CHUNK = 600  # sys.int_max_str_digits の最小値 640 より小さい


def _digits_to_int(digits):
    cache = {}

    def convert(start, end):
        length = end - start
        if length <= _INT_CHUNK:
            return int(digits[start:end])
        half = length // 2
        mid = end - half
        power = cache.get(half)
        if power is None:
            power = 10 ** half
            cache[half] = power
        return convert(start, mid) * power + convert(mid, end)

    return convert(0, len(digits))


def _to_int(number_text):
    if len(number_text) <= _INT_CHUNK:
        return int(number_text)
    limit = sys.get_int_max_str_digits() if hasattr(sys, 'get_int_max_str_digits') else 0
    if limit == 0 or len(number_text) <= limit:
        return int(number_text)
    negative = number_text[0] == '-'
    digits = number_text[1:] if negative else number_text
    result = _digits_to_int(digits)
    return -result if negative else result


def _hex4(text, pos):
    match = _HEX4_MATCH(text, pos)
    if match is None:
        raise ValueError(f'invalid \\u escape at position {pos}')
    return int(match.group(), 16)


def _parse_string(text, pos, length):
    # text[pos] == '"'
    simple = _SIMPLE_STRING_MATCH(text, pos)
    if simple is not None:
        return simple.group(1), simple.end()
    parts = []
    pos += 1
    while True:
        chunk = _STRING_CHUNK_MATCH(text, pos)
        end = chunk.end()
        if end > pos:
            parts.append(text[pos:end])
        pos = end
        if pos >= length:
            raise ValueError('unterminated string')
        current = text[pos]
        if current == '"':
            return ''.join(parts), pos + 1
        if current != '\\':
            raise ValueError(f'unescaped control character at position {pos}')
        if pos + 1 >= length:
            raise ValueError('unterminated escape sequence')
        escape = text[pos + 1]
        if escape == 'u':
            code = _hex4(text, pos + 2)
            pos += 6
            if 0xD800 <= code <= 0xDBFF:
                if not text.startswith('\\u', pos):
                    raise ValueError(f'lone high surrogate at position {pos}')
                low = _hex4(text, pos + 2)
                if not (0xDC00 <= low <= 0xDFFF):
                    raise ValueError(f'invalid low surrogate at position {pos}')
                code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                pos += 6
            elif 0xDC00 <= code <= 0xDFFF:
                raise ValueError(f'lone low surrogate at position {pos}')
            parts.append(chr(code))
        else:
            replacement = _ESCAPES.get(escape)
            if replacement is None:
                raise ValueError(f'invalid escape at position {pos}')
            parts.append(replacement)
            pos += 2


def _read_key(text, pos, length, obj):
    if pos >= length or text[pos] != '"':
        raise ValueError(f'expected string key at position {pos}')
    key, pos = _parse_string(text, pos, length)
    if key in obj:
        raise ValueError(f'duplicate key {key!r}')
    pos = _WS_MATCH(text, pos).end()
    if pos >= length or text[pos] != ':':
        raise ValueError(f'expected ":" at position {pos}')
    return key, _WS_MATCH(text, pos + 1).end()


def parse_json(text: str) -> object:
    if not isinstance(text, str):
        raise TypeError('text must be str')
    length = len(text)
    ws = _WS_MATCH
    pos = ws(text, 0).end()
    stack = []  # 各要素は [container, key]（list のときの key は未使用）
    while True:
        # ---- 値を 1 つ読む ----
        if pos >= length:
            raise ValueError('unexpected end of input')
        current = text[pos]
        if current == '"':
            value, pos = _parse_string(text, pos, length)
        elif current == '{':
            pos = ws(text, pos + 1).end()
            if pos < length and text[pos] == '}':
                value = {}
                pos += 1
            else:
                obj = {}
                key, pos = _read_key(text, pos, length, obj)
                stack.append([obj, key])
                continue
        elif current == '[':
            pos = ws(text, pos + 1).end()
            if pos < length and text[pos] == ']':
                value = []
                pos += 1
            else:
                stack.append([[], None])
                continue
        elif current == 't':
            if not text.startswith('true', pos):
                raise ValueError(f'invalid literal at position {pos}')
            value = True
            pos += 4
        elif current == 'f':
            if not text.startswith('false', pos):
                raise ValueError(f'invalid literal at position {pos}')
            value = False
            pos += 5
        elif current == 'n':
            if not text.startswith('null', pos):
                raise ValueError(f'invalid literal at position {pos}')
            value = None
            pos += 4
        else:
            match = _NUMBER_MATCH(text, pos)
            if match is None:
                raise ValueError(f'unexpected character at position {pos}')
            number_text = match.group()
            pos = match.end()
            if match.group(1) is None and match.group(2) is None:
                value = _to_int(number_text)
            else:
                value = float(number_text)

        # ---- 親へ付け、閉じられる入れ物を閉じる ----
        while True:
            if not stack:
                pos = ws(text, pos).end()
                if pos != length:
                    raise ValueError(f'extra data at position {pos}')
                return value
            frame = stack[-1]
            container = frame[0]
            if type(container) is list:
                container.append(value)
                closer = ']'
            else:
                container[frame[1]] = value
                closer = '}'
            pos = ws(text, pos).end()
            if pos >= length:
                raise ValueError('unexpected end of input')
            current = text[pos]
            if current == ',':
                pos = ws(text, pos + 1).end()
                if closer == '}':
                    frame[1], pos = _read_key(text, pos, length, container)
                break
            if current == closer:
                pos += 1
                stack.pop()
                value = container
                continue
            raise ValueError(f'unexpected character at position {pos}')
